{"path": "/tmp/task.1NQmM4xGNe/work/test_duration.py", "content": "import unittest
from duration import parse_duration


class TestParseDuration(unittest.TestCase):
    def test_simple_seconds(self):
        self.assertEqual(parse_duration("45s"), 45)

    def test_minutes(self):
        self.assertEqual(parse_duration("1m"), 60)

    def test_hours(self):
        self.assertEqual(parse_duration("1h"), 3600)

    def test_days(self):
        self.assertEqual(parse_duration("1d"), 86400)

    def test_combined_1h30m(self):
        # 1h30m = 3600 + 1800 = 5400
        self.assertEqual(parse_duration("1h30m"), 5400)

    def test_combined_1d2h(self):
        # 1d2h = 86400 + 7200 = 93600
        self.assertEqual(parse_duration("1d2h"), 93600)

    def test_case_insensitive(self):
        self.assertEqual(parse_duration("1H30M"), 5400)

    def test_whitespace_around(self):
        self.assertEqual(parse_duration(" 1H 30M "), 5400)

    def test_whitespace_between_parts(self):
        self.assertEqual(parse_duration("1 H 30 M"), 5400)

    def test_empty_string(self):
        with self.assertRaises(ValueError):
            parse_duration("")

    def test_bare_number_no_unit(self):
        with self.assertRaises(ValueError):
            parse_duration("10")

    def test_unknown_unit(self):
        with self.assertRaises(ValueError):
            parse_duration("1x")

    def test_repeated_unit(self):
        with self.assertRaises(ValueError):
            parse_duration("1h1h")

    def test_negative_number(self):
        with self.assertRaises(ValueError):
            parse_duration("-1h")

    def test_decimal(self):
        with self.assertRaises(ValueError):
            parse_duration("1.5h")

    def test_ascending_order_invalid(self):
        with self.assertRaises(ValueError):
            parse_duration("1s1m1h")  # s,m,h is ascending (reverse descending)

    def test_descending_order_valid(self):
        # 1d2h3m4s = 86400 + 7200 + 180 + 4 = 93784
        self.assertEqual(parse_duration("1d2h3m4s"), 93784)

    def test_missing_intermediate_units_ok(self):
        # Skipping units is fine, e.g. "1d3s" = 86400 + 3
        self.assertEqual(parse_duration("1d3s"), 86403)

    def test_repeated_unit_at_end(self):
        with self.assertRaises(ValueError):
            parse_duration("1d1h1m1s1d")  # repeated d


if __name__ == "__main__":
    unittest.main()"}
